#!/usr/bin/env python3
"""Native grip/stir regression; persisted fixtures are generated by trusted SI modules."""
from pathlib import Path
source=Path('checks/browser-thermal-v87.py').read_text()
exec(compile(source[:source.index('\nCASES=')],'checks/browser-thermal-v87.py','exec'))
node="""import{createState,applyAction,validateState}from'./dist/l3/thermal-physics.js';import{initialPositions,probePlacementAt}from'./dist/l3/thermal-apparatus.js';import{newSession,newTrial,serializeSession,parseSession}from'./dist/l3/data-notebook.js';let s={...createState('solid'),apparatusGeometryVersion:'thermal.geometry.v2'};for(const[actionType,payloadSI]of[['place-vessel',{placed:true}],['pour',{massKg:.2,target:'vessel'}],['place-probe',{placement:'water'}]])s=applyAction(s,{actionType,payloadSI}).state;const q=newSession('solid');newTrial(q,'solid',{waterMassKg:.2,waterTempK:293.15});q.physicalState=s;q.apparatusState={positions:{...initialPositions(s),stirrer:{x:410,y:310},probe:{x:425,y:310}},cupAngleRad:0,camera:null,geometryVersion:'thermal.geometry.v2'};if(probePlacementAt(q.apparatusState.positions.probe,s,q.apparatusState.positions)!=='water')throw Error('contact');const raw=serializeSession(q);parseSession(raw,{activity:'solid',validateState:s=>validateState(s).valid});process.stdout.write(raw);"""
fixture=json.loads(subprocess.check_output(['node','--input-type=module','-e',node],text=True))
results=[];before=source_hashes()
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=args.chromium,headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 for width,view,touch in ([(1440,'3d',False)] if args.only=='before' else [(1440,'3d',False),(390,'3d',True),(844,'3d',True),(1440,'2d',False),(390,'2d',True)]):
  b=Bench(browser,'solid',width=width,height=900,force_2d=view=='2d',preloaded=fixture);p=b.page
  try:
   b.select('calorimeter');stage=p.locator('#l3ThreeCanvas' if view=='3d' else '#l3Stage');stage.scroll_into_view_if_needed();p.wait_for_timeout(250)
   def screen(x,y):
    if view=='3d':return b.screen(x,y)
    return stage.evaluate('(s,p)=>{const m=s.getScreenCTM(),q=s.createSVGPoint();q.x=p.x;q.y=p.y;const r=q.matrixTransform(m);return{x:r.x,y:r.y}}',{'x':x,'y':y})
   # Start on submerged paddle, while a different tool is selected. No palette shortcut.
   origin=screen(410,320);cdp=b.context.new_cdp_session(p) if touch else None
   def pointer(kind,q):
    if touch:cdp.send('Input.dispatchTouchEvent',{'type':kind,'touchPoints':[] if kind=='touchEnd' else [{'x':q['x'],'y':q['y'],'id':0,'radiusX':4,'radiusY':4,'force':1}]})
    elif kind=='touchStart':p.mouse.move(q['x'],q['y']);p.mouse.down()
    elif kind=='touchMove':p.mouse.move(q['x'],q['y'])
    else:p.mouse.up()
   pointer('touchStart',origin)
   if view=='3d':grabbed=p.locator('.l3-three-shell').get_attribute('data-dragging')
   else:grabbed=None
   for i in range(1,38):
    a=i*math.pi/12;q=screen(410+10*math.cos(a),315.6666666667+10*math.sin(a))
    pointer('touchMove',q)
   pointer('touchEnd',origin);p.wait_for_timeout(1000);s=b.session();events=[e for e in s['trials'][0]['events'] if e['actionType']=='stir' and e['accepted']]
   if args.only=='before':
    b.canvas_pixels('before-immersed-rod');results.append({'viewport':width,'view':view,'grabbed':grabbed,'stirEvents':len(events),'defectReproduced':grabbed!='stirrer' and not events,'pageErrors':b.errors[:]});continue
   assert (grabbed=='stirrer' if view=='3d' else p.locator('#l3SelectedTool').inner_text()=='Que khuấy'),{'grabbed':grabbed,'selectedTool':p.locator('#l3SelectedTool').inner_text()}
   assert events and s['physicalState']['mixingIntensity']>0,{'stirEvents':len(events),'positions':s['apparatusState']['positions']['stirrer']}
   assert s['apparatusState']['positions']['calorimeter']==fixture['apparatusState']['positions']['calorimeter']
   assert p.locator('.l3-three-labels,.l3-three-label').count()==0
   assert p.locator('#l3Stage .l3-svg-label').count()==0
   assert not b.errors;b.invariant();pause_if_running(b)
   p.screenshot(path=str(out/f'after-{view}-{width}.png'),full_page=True)
   results.append({'viewport':width,'view':view,'touchEmulated':touch,'directSubmergedGrip':True,'stirEvents':len(events),'mixingIntensity':s['physicalState']['mixingIntensity'],'calorimeterUnchanged':True,'floatingNamesRemoved':True,'pageErrors':b.errors[:]})
   print(json.dumps(results[-1],ensure_ascii=False),flush=True)
  finally:b.close()
 version=browser.version;browser.close()
after=source_hashes();assert before==after
(out/'report.json').write_text(json.dumps({'status':'REPRODUCED' if args.only=='before' else 'PASS','browserVersion':version,'results':results,'sourceBefore':before,'sourceAfter':after,'sourceStable':True,'scope':'Native mouse/CDP touch; software WebGL. No physical device acceptance.'},ensure_ascii=False,indent=2)+'\n');print(json.dumps({'results':results,'sourceStable':True},ensure_ascii=False))
